// ─── SEARCH SYNONYMS ────────────────────────────────────────────────────────
// Abbreviation → specific phrases matched as substrings of the type name.
// Only non-literal abbreviations (where the resource is named differently than
// the acronym); literal terms like "dns"/"sql" already match the name directly.
const ABBREV = {
  vm: ["virtual machine"], vms: ["virtual machine"],
  nic: ["network interface"], nsg: ["network security group"],
  vnet: ["virtual network"], aks: ["managed cluster", "kubernetes"],
  acr: ["container registr"], avd: ["host pool", "session host", "application group"],
  rg: ["resource group"], lb: ["load balancer"], kv: ["key vault"],
  pip: ["public ip"], k8s: ["kubernetes", "managed cluster"],
};

// Returns { filtered: categories, isPermSearch: bool, permQuery: string }
function searchMatch(query, categories) {
  if (!query.trim()) return { filtered: categories, isPermSearch: false, permQuery: "" };
  const q = query.toLowerCase().trim();
  
  // Prevent expanding all categories when the user is just typing the common prefix
  const isGeneric = /^(m|mi|mic|micr|micro|micros|microso|microsof|microsoft|microsoft\.)$/i.test(q);
  if (isGeneric) return { filtered: categories, isPermSearch: false, permQuery: "", isGeneric: true };

  // Mode 1: explicit permission path (contains / or microsoft.)
  if (q.includes("/") || q.includes("microsoft.")) {
    const f = categories.map(cat => ({ ...cat, providers: cat.providers.map(p => ({ ...p, types: p.types.filter(t => t.actions.some(a => a.ops.some(o => o.action.toLowerCase().includes(q)))) })).filter(p => p.types.length > 0) })).filter(c => c.providers.length > 0);
    return { filtered: f, isPermSearch: true, permQuery: q };
  }
  // Mode 2: plain-word search — a type matches if its OWN name matches
  // (word-boundary, abbreviation-aware) OR one of its operations matches (the
  // op tail, namespace stripped, so "deallocate"/"blob" find the right types).
  // Ignores the category/provider name and the namespace so results stay tight;
  // the tree renders matches collapsed with the matching level marked.
  const words = q.split(/\s+/).filter(Boolean);
  const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const f = categories.map(cat => ({
    ...cat, providers: cat.providers.map(p => {
      const nsPrefix = (p.namespace + "/").toLowerCase();
      return {
        ...p, types: p.types.filter(t => {
          const nameHay = (t.name + " " + t.key).toLowerCase();
          const nameMatch = words.every(w => {
            if (new RegExp("\\b" + esc(w), "i").test(nameHay)) return true;
            if (ABBREV[w]) return ABBREV[w].some(ph => nameHay.includes(ph));
            return false;
          });
          if (nameMatch) return true;
          return t.actions.some(a => a.ops.some(o => {
            const l = o.action.toLowerCase();
            const tail = l.startsWith(nsPrefix) ? l.slice(nsPrefix.length) : l;
            return words.every(w => tail.includes(w));
          }));
        })
      };
    }).filter(p => p.types.length > 0)
  })).filter(c => c.providers.length > 0);
  return { filtered: f, isPermSearch: false, permQuery: "" };
}

// Highlight matching text in a string
function HL({ text, query }) {
  if (!query || query.length < 2) return text;
  const words = query.toLowerCase().split(/\s+/).filter(w => w.length >= 2);
  // Also add abbreviation expansions
  const allWords = [...words];
  for (const w of words) if (ABBREV[w]) allWords.push(...ABBREV[w].flatMap(ph => ph.split(/\s+/)).filter(s => s.length >= 2));
  if (!allWords.length) return text;
  const pat = allWords.map(w => w.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")).join("|");
  const splitRe = new RegExp(`(${pat})`, "gi");
  const testRe = new RegExp(`^(?:${pat})$`, "i"); // non-global: stateless, reliable per-part test
  const parts = text.split(splitRe);
  return parts.map((p, i) => testRe.test(p)
    ? <mark key={i} style={{ color: "#eaf7ff", fontWeight: 700, background: "rgba(79,195,247,0.28)", borderRadius: 3, padding: "0 3px", boxShadow: "0 0 0 1px rgba(79,195,247,0.4)" }}>{p}</mark>
    : p);
}

